package org.apache.commons.lang3.math;

import java.io.*;
import java.lang.reflect.Array;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen1Test {





    @Test
    public void testCreateNumber_HexInteger() throws NumberFormatException {
        assertEquals(Integer.class, NumberUtils.createNumber("0x123").getClass());
        assertEquals(Integer.class, NumberUtils.createNumber("0X123").getClass());
        assertEquals(Integer.class, NumberUtils.createNumber("#123").getClass());
        assertEquals(Long.class, NumberUtils.createNumber("0x7FFFFFFFFFFFFFFF").getClass());
        assertEquals(BigInteger.class, NumberUtils.createNumber("0x7FFFFFFFFFFFFFFF1").getClass());
        assertEquals(Long.class, NumberUtils.createNumber("-0x123").getClass());
        assertEquals(Long.class, NumberUtils.createNumber("-#123").getClass());
        // Test leading zeros in hex
        assertEquals(Integer.class, NumberUtils.createNumber("0x0001").getClass());
    }




























}

